package fingerprint

import (
	"encoding/hex"
	"testing"

	"github.com/wi1dcard/fingerproxy/pkg/ja4"
	"github.com/wi1dcard/fingerproxy/pkg/metadata"
)

func TestJA4StableFingerprintMatchesJA4Package(t *testing.T) {
	clientHelloRecord, err := hex.DecodeString("")
	if err != nil {
		t.Fatal(err)
	}

	data := &metadata.Metadata{ClientHelloRecord: clientHelloRecord}

	got, err := JA4StableFingerprint(data)
	if err != nil {
		t.Fatal(err)
	}

	expected := &ja4.StableJA4Fingerprint{}
	if err := expected.UnmarshalBytes(clientHelloRecord, 't'); err != nil {
		t.Fatal(err)
	}

	if got != expected.String() {
		t.Fatalf("expected %s, got %s", expected.String(), got)
	}
}
